(2911503, 407203, 50695, '<td valign="top">your shadow is a little too spunky. A N X I E T Y was better. <a href="//www.dpchallenge.com/image.php?IMAGE_ID=405499" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/564/thumb/405499.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/564/thumb/405499.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/564/thumb/405499.jpg"/></a> (it''s still a good picture, btw. I just didn''t feel it showed "despair." I gave it a 6)<br/><br/><i>Message edited by author 2006-10-16 14:51:01.</i></td>', 'your shadow is a little too spunky. A N X I E T Y was better.  (it''s still a good picture, btw. I just didn''t feel it showed "despair." I gave it a 6)', '2006-10-09 13:45:16.000000', '2006-10-16 15:51:01.000000', 1),
(2911517, 408038, 60343, '<td valign="top">Love it. Fine controlled lighting to yield texture and shape. Strong composition. Meets the challenge by revealing the subject through his hands at work. If you can''t show the face, the hands are the way to go. Well done.</td>', 'Love it. Fine controlled lighting to yield texture and shape. Strong composition. Meets the challenge by revealing the subject through his hands at work. If you can''t show the face, the hands are the way to go. Well done.', '2006-10-09 13:51:28.000000', NULL, 1),
(2911526, 408500, 60343, '<td valign="top">Nice. Reminds me of Avedon''s fashion work.</td>', 'Nice. Reminds me of Avedon''s fashion work.', '2006-10-09 13:54:34.000000', NULL, 1),
(2911537, 408110, 60343, '<td valign="top">Clever. Cool and appealing workaround to the challenge. Has a "found" look to it even if it isn''t and if it is, priceless.</td>', 'Clever. Cool and appealing workaround to the challenge. Has a "found" look to it even if it isn''t and if it is, priceless.', '2006-10-09 13:59:10.000000', NULL, 1),
(2911538, 408092, 60343, '<td valign="top">Nice figure study, finely lit to reveal form. Would have liked to see the subject moved a bit left in the frame. Well done.</td>', 'Nice figure study, finely lit to reveal form. Would have liked to see the subject moved a bit left in the frame. Well done.', '2006-10-09 14:00:06.000000', NULL, 1),
