(2915305, 408038, 65234, '<td valign="top">Excellent idea!  I might have liked to see the other hand in a bit better focus but this is a terrific faceless portrait.</td>', 'Excellent idea!  I might have liked to see the other hand in a bit better focus but this is a terrific faceless portrait.', '2006-10-10 20:30:39.000000', NULL, 1),
(2915311, 406987, 65234, '<td valign="top">There''s a lot to like in this image and it''s nicely emotive.</td>', 'There''s a lot to like in this image and it''s nicely emotive.', '2006-10-10 20:33:00.000000', NULL, 1),
(2915312, 408092, 25754, '<td valign="top">absolutely beautiful portrait! lighting, tone and mood are perfect.</td>', 'absolutely beautiful portrait! lighting, tone and mood are perfect.', '2006-10-10 20:33:23.000000', NULL, 1),
(2915314, 408422, 65234, '<td valign="top">Definitely get a sense of how busy a teacher is, and the motion in the hands emphasizes that nicely.</td>', 'Definitely get a sense of how busy a teacher is, and the motion in the hands emphasizes that nicely.', '2006-10-10 20:34:21.000000', NULL, 1),
(2915315, 408485, 65234, '<td valign="top">Good emotion in this one and nice composition.</td>', 'Good emotion in this one and nice composition.', '2006-10-10 20:35:25.000000', NULL, 1),
(2915318, 407616, 65234, '<td valign="top">Nice emotive image that shows one of the simple joys of being a child.</td>', 'Nice emotive image that shows one of the simple joys of being a child.', '2006-10-10 20:36:43.000000', NULL, 1),
(2915319, 406146, 25754, '<td valign="top">This could have been way more moodier/lusty with subtle lighting.</td>', 'This could have been way more moodier/lusty with subtle lighting.', '2006-10-10 20:37:10.000000', NULL, 1),
(2915323, 408432, 65234, '<td valign="top">Nicely balanced and just enough detail and content to make the title almost unnecessary.  Good image for this challenge.</td>', 'Nicely balanced and just enough detail and content to make the title almost unnecessary.  Good image for this challenge.', '2006-10-10 20:38:24.000000', NULL, 1),
(2915325, 407424, 65234, '<td valign="top">I like the sepia and the many different lines in this image.</td>', 'I like the sepia and the many different lines in this image.', '2006-10-10 20:39:02.000000', NULL, 1),
(2915327, 408275, 65234, '<td valign="top">Love the reflection and the title adds a lot to the image.  Very nicely done.</td>', 'Love the reflection and the title adds a lot to the image.  Very nicely done.', '2006-10-10 20:40:29.000000', NULL, 1),
(2915328, 408283, 65234, '<td valign="top">I like the use of sepia and showing the whittling; I think I would have liked it better with a tighter crop on the hands.</td>', 'I like the use of sepia and showing the whittling; I think I would have liked it better with a tighter crop on the hands.', '2006-10-10 20:41:24.000000', NULL, 1),
(2915331, 407520, 65234, '<td valign="top">Image is a little dark but very powerful composition.</td>', 'Image is a little dark but very powerful composition.', '2006-10-10 20:42:55.000000', NULL, 1),
(2915336, 407536, 65234, '<td valign="top">Nicely emotive.</td>', 'Nicely emotive.', '2006-10-10 20:44:33.000000', NULL, 1),
(2915341, 407952, 65234, '<td valign="top">Like the idea but the blurring looks overdone, especially on the tips of the fingers.</td>', 'Like the idea but the blurring looks overdone, especially on the tips of the fingers.', '2006-10-10 20:46:23.000000', NULL, 1),
(2915343, 408046, 65234, '<td valign="top">Great idea; a little darker on the bottom of the book and hands than I would like.</td>', 'Great idea; a little darker on the bottom of the book and hands than I would like.', '2006-10-10 20:47:32.000000', NULL, 1),
(2915349, 407002, 65234, '<td valign="top">Lovely colors and composition!  The hands being in motion is a nice touch.  I hope this is not truly representative of the mental state of the subject!!</td>', 'Lovely colors and composition!  The hands being in motion is a nice touch.  I hope this is not truly representative of the mental state of the subject!!', '2006-10-10 20:49:14.000000', NULL, 1),
(2915357, 405518, 65234, '<td valign="top">I like the concept but I don''t think there is enough context in the picture to tell that this is anything but a person bending over with some specks of something on her shirt.</td>', 'I like the concept but I don''t think there is enough context in the picture to tell that this is anything but a person bending over with some specks of something on her shirt.', '2006-10-10 20:51:02.000000', NULL, 1),
(2915370, 408554, 65234, '<td valign="top">I like the composition with the birds and the sign and the bucket and the boats in the background.  The color of the sky and lighting are very nice.</td>', 'I like the composition with the birds and the sign and the bucket and the boats in the background.  The color of the sky and lighting are very nice.', '2006-10-10 20:54:39.000000', NULL, 1),
(2915375, 408224, 65234, '<td valign="top">Dramatic colors!  Nice shot.</td>', 'Dramatic colors!  Nice shot.', '2006-10-10 20:55:31.000000', NULL, 1),
(2915385, 406591, 65234, '<td valign="top">Cousin It!!!</td>', 'Cousin It!!!', '2006-10-10 20:58:54.000000', NULL, 1),
(2915388, 407892, 65234, '<td valign="top">That is seriously disturbing!</td>', 'That is seriously disturbing!', '2006-10-10 21:00:37.000000', NULL, 1),
(2915412, 407667, 65234, '<td valign="top">The head of the drum major is a little dark but I love the composition and the DOF with the crowd in the background.</td>', 'The head of the drum major is a little dark but I love the composition and the DOF with the crowd in the background.', '2006-10-10 21:05:39.000000', NULL, 1),
(2915510, 408257, 20462, '<td valign="top">cool..well thought out.</td>', 'cool..well thought out.', '2006-10-10 21:36:08.000000', NULL, 1),
(2915515, 407667, 20462, '<td valign="top">not CU, CU...oh gosh.  the photograph is well done though, it certainly makes sense we don''t see his face...</td>', 'not CU, CU...oh gosh.  the photograph is well done though, it certainly makes sense we don''t see his face...', '2006-10-10 21:37:26.000000', NULL, 1),
(2915522, 408275, 20462, '<td valign="top">Positives:  Tones, color, concept<br/>Negatives:  a touch overexposed, doesn''t exactly reveal a human in portraiture.<br/>Overall:  Nice idea, well executed, should finish in middle of the pack, the reflection is coolest part...</td>', 'Positives:  Tones, color, conceptNegatives:  a touch overexposed, doesn''t exactly reveal a human in portraiture.Overall:  Nice idea, well executed, should finish in middle of the pack, the reflection is coolest part...', '2006-10-10 21:40:24.000000', NULL, 1),
(2915548, 408010, 23484, '<td valign="top">The softness in this photo really makes this shot.  Good job.</td>', 'The softness in this photo really makes this shot.  Good job.', '2006-10-10 21:52:02.000000', NULL, 1),
