INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2915862, 406151, 13688, '<td valign="top">this is fantastic.  extremely dark and moody.  just the right amount of lighting. odd how your border and title almost ruin your composition for me :(  please take more of these kind of images...please don''t border them ;)</td>', 'this is fantastic.  extremely dark and moody.  just the right amount of lighting. odd how your border and title almost ruin your composition for me :(  please take more of these kind of images...please don''t border them ;)', '2006-10-10 23:31:46.000000', NULL, 1),
