(2915984, 408098, 15407, '<td valign="top">Yes a slow painful DEATH... worse for the family and friends that have to watch it happen.</td>', 'Yes a slow painful DEATH... worse for the family and friends that have to watch it happen.', '2006-10-11 00:15:08.000000', NULL, 1),
(2916078, 408092, 66663, '<td valign="top">love the lighting, great shadows.</td>', 'love the lighting, great shadows.', '2006-10-11 00:52:56.000000', NULL, 1),
(2916139, 408487, 42826, '<td valign="top">oh that''s an interesting texture...i like the composition and the coloring makes this shot fit with the title...very interesting!</td>', 'oh that''s an interesting texture...i like the composition and the coloring makes this shot fit with the title...very interesting!', '2006-10-11 01:07:12.000000', NULL, 1),
