(2919673, 407278, 3087, '<td valign="top">Lovely backlighting and silhouette and love the symbolism of the woman standing in the doorway looking out over the sunny garden, out into life and at the same time stretching and readying herself for it...</td>', 'Lovely backlighting and silhouette and love the symbolism of the woman standing in the doorway looking out over the sunny garden, out into life and at the same time stretching and readying herself for it...', '2006-10-11 18:12:36.000000', NULL, 1),
(2919675, 408523, 3087, '<td valign="top">Good choice of surface in terms of colour, texture and geometry of the slab edges. Muted and dark colours contribute to the feeling of sadness and despair.</td>', 'Good choice of surface in terms of colour, texture and geometry of the slab edges. Muted and dark colours contribute to the feeling of sadness and despair.', '2006-10-11 18:13:54.000000', NULL, 1),
(2919790, 406551, 14614, '<td valign="top">just the right exposure, framing, and composition.  One of my ribbon picks.</td>', 'just the right exposure, framing, and composition.  One of my ribbon picks.', '2006-10-11 18:45:01.000000', NULL, 1),
(2919797, 408330, 14614, '<td valign="top">intersting composition and duo-tones.  the mix of both creates a great tension in the shot.  One of my ribbon picks.</td>', 'intersting composition and duo-tones.  the mix of both creates a great tension in the shot.  One of my ribbon picks.', '2006-10-11 18:46:05.000000', NULL, 1),
