(2919825, 408554, 48890, '<td valign="top">Need to be careful to separate the objects in the frame.  It looks as though the ship on the right is hanging off the fishing line, and the boat on the left is stuck with the fisher''s body.  A couple of steps left would have fixed both problems.</td>', 'Need to be careful to separate the objects in the frame.  It looks as though the ship on the right is hanging off the fishing line, and the boat on the left is stuck with the fisher''s body.  A couple of steps left would have fixed both problems.', '2006-10-11 18:50:15.000000', NULL, 1),
(2919830, 408213, 14614, '<td valign="top">the muted tones and pose show a sensitivity that a "face" portrait would not have been able to capture.  The diagonal compostion is well-done One of my favorites this challenge</td>', 'the muted tones and pose show a sensitivity that a "face" portrait would not have been able to capture.  The diagonal compostion is well-done One of my favorites this challenge', '2006-10-11 18:51:10.000000', NULL, 1),
(2919835, 405404, 14614, '<td valign="top">so imaginative... I think I would have liked the subject''s head straight (instead of bent down)  One of my favorites this challenge</td>', 'so imaginative... I think I would have liked the subject''s head straight (instead of bent down)  One of my favorites this challenge', '2006-10-11 18:52:31.000000', NULL, 1),
(2919836, 408229, 48890, '<td valign="top">This shot looks completely fake/set up.</td>', 'This shot looks completely fake/set up.', '2006-10-11 18:52:33.000000', NULL, 1),
