INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2919856, 407424, 6999, '<td valign="top">I like what i see as the intent of this - reminiscent of those American deep south documentary photographers - but the execution is poor here: contrast, resolution, processing, all are kind of messy and uncontrolled I think. That said, you evidently have an eye - the horizontal lines of his shirt, the vertical lines of the bar, the distorted lines reflected in the stools'' seats and the diagonal lines of the padding behind the counter make for an interesting composition. I just really wish you''d had a better quality image. 7 for the eye, and the other three off for the quality issues.</td>', 'I like what i see as the intent of this - reminiscent of those American deep south documentary photographers - but the execution is poor here: contrast, resolution, processing, all are kind of messy and uncontrolled I think. That said, you evidently have an eye - the horizontal lines of his shirt, the vertical lines of the bar, the distorted lines reflected in the stools'' seats and the diagonal lines of the padding behind the counter make for an interesting composition. I just really wish you''d had a better quality image. 7 for the eye, and the other three off for the quality issues.', '2006-10-11 18:55:29.000000', NULL, 1),
(2919859, 407203, 20435, '<td valign="top">nice</td>', 'nice', '2006-10-11 18:56:31.000000', NULL, 1),
(2919861, 407510, 14614, '<td valign="top">very inventive ... always a technique that makes me study the photo and wonder how.  One of my favorites this challenge</td>', 'very inventive ... always a technique that makes me study the photo and wonder how.  One of my favorites this challenge', '2006-10-11 18:56:40.000000', NULL, 1),
(2919863, 408228, 14614, '<td valign="top">the lighting and tones make this a standout.  One of my favorites this challenge</td>', 'the lighting and tones make this a standout.  One of my favorites this challenge', '2006-10-11 18:57:07.000000', NULL, 1),
(2919865, 408110, 20435, '<td valign="top">I just love this photo. Very creative and the face on the mag fits in so well. Great job! 10 from me.</td>', 'I just love this photo. Very creative and the face on the mag fits in so well. Great job! 10 from me.', '2006-10-11 18:57:55.000000', NULL, 1),
(2919866, 407987, 14614, '<td valign="top">edgy and provacative.  lighting works combines to add to the energy. One of my favorites this challenge</td>', 'edgy and provacative.  lighting works combines to add to the energy. One of my favorites this challenge', '2006-10-11 18:58:02.000000', NULL, 1),
(2919869, 408521, 6999, '<td valign="top">Quite fun, and with a certain obsessive madness feeling that I certainly associate with surfers. There''s a stange sugestion of nudity - simply because all visible body is unclothed, and we''re inculcated with the idea that any concealed area of flesh must therefore be unclothed.</td>', 'Quite fun, and with a certain obsessive madness feeling that I certainly associate with surfers. There''s a stange sugestion of nudity - simply because all visible body is unclothed, and we''re inculcated with the idea that any concealed area of flesh must therefore be unclothed.', '2006-10-11 18:58:14.000000', NULL, 1),
(2919870, 408494, 20435, '<td valign="top">I lvoe this, very creative and the lighting is nice.</td>', 'I lvoe this, very creative and the lighting is nice.', '2006-10-11 18:58:40.000000', NULL, 1),
(2919873, 407628, 20435, '<td valign="top">this is nice. The colors are stunning.</td>', 'this is nice. The colors are stunning.', '2006-10-11 18:59:35.000000', NULL, 1),
(2919874, 408209, 14614, '<td valign="top">a bit creepy ... very evocative ... like the gritty duotones ... One of my favorites this challenge</td>', 'a bit creepy ... very evocative ... like the gritty duotones ... One of my favorites this challenge', '2006-10-11 18:59:38.000000', NULL, 1),
(2919877, 408260, 20435, '<td valign="top">I love this photo. Love the colors and lighting. Seems so dark yet so classy.</td>', 'I love this photo. Love the colors and lighting. Seems so dark yet so classy.', '2006-10-11 19:00:32.000000', NULL, 1),
(2919880, 408015, 20435, '<td valign="top">Nice photo.</td>', 'Nice photo.', '2006-10-11 19:01:12.000000', NULL, 1),
(2919881, 408500, 6999, '<td valign="top">Is the double entendre deliberate? Your framing actually suggests so, in which case I make this a very clever shot. I would wish it had a bit more punch, but I''m a high contrast fan, so that''s an ignorable comment.</td>', 'Is the double entendre deliberate? Your framing actually suggests so, in which case I make this a very clever shot. I would wish it had a bit more punch, but I''m a high contrast fan, so that''s an ignorable comment.', '2006-10-11 19:01:16.000000', NULL, 1),
(2919884, 405170, 14614, '<td valign="top">playful ... good connection between you and your model ... odd bit of hair/finger/thing near model''s nose detracts as it draws my attention off the full compostion ... One of my favorites this challenge</td>', 'playful ... good connection between you and your model ... odd bit of hair/finger/thing near model''s nose detracts as it draws my attention off the full compostion ... One of my favorites this challenge', '2006-10-11 19:02:06.000000', NULL, 1),
(2919893, 406903, 6999, '<td valign="top">I was going to say it''s a pretentious title, but actually i think it''s a pretentious image as well. Itr has elements of that James Dean thing - ''look! I''m wearing leather and denim, so I must be a ''real'' man, and yet my pose makes it evident that actually, deep underneath, I''m a deeply tortured artistic and unconfident soul!'' thing. Kind of unlikeable, really.</td>', 'I was going to say it''s a pretentious title, but actually i think it''s a pretentious image as well. Itr has elements of that James Dean thing - ''look! I''m wearing leather and denim, so I must be a ''real'' man, and yet my pose makes it evident that actually, deep underneath, I''m a deeply tortured artistic and unconfident soul!'' thing. Kind of unlikeable, really.', '2006-10-11 19:03:44.000000', NULL, 1),
(2919905, 406151, 6999, '<td valign="top">Just seems so unpleasntly posed - especialy with that key-line.</td>', 'Just seems so unpleasntly posed - especialy with that key-line.', '2006-10-11 19:05:06.000000', NULL, 1),
(2919992, 408487, 45475, '<td valign="top">I typically do like grain in monotoned images, but I''m not sure it''s done you any favours here. I guess it may be because I''d prefer to see ''flesh'' as smooth and as something that would be wonderful to touch, but the overall feeling I get here is gritty and hard. I see you''ve softened the highlights somewhat (diffused glow?) and that does help to a certain degree. Also. I think your subject''s pose and title match perfectly and do well to aid the viewer in believing the message you''re conveying. Well done, if this is an sp, I think you are very brave. Cheers, Rina.</td>', 'I typically do like grain in monotoned images, but I''m not sure it''s done you any favours here. I guess it may be because I''d prefer to see ''flesh'' as smooth and as something that would be wonderful to touch, but the overall feeling I get here is gritty and hard. I see you''ve softened the highlights somewhat (diffused glow?) and that does help to a certain degree. Also. I think your subject''s pose and title match perfectly and do well to aid the viewer in believing the message you''re conveying. Well done, if this is an sp, I think you are very brave. Cheers, Rina.', '2006-10-11 19:30:17.000000', NULL, 1),
(2919997, 406892, 3087, '<td valign="top">Great lighting, especially where it catches the stubble, love the bokeh, the tilt works well, it''s all good!</td>', 'Great lighting, especially where it catches the stubble, love the bokeh, the tilt works well, it''s all good!', '2006-10-11 19:32:08.000000', NULL, 1),
(2919999, 408490, 3087, '<td valign="top">Not sure this reveals anything about the subject but it''s fun and cleverly done!</td>', 'Not sure this reveals anything about the subject but it''s fun and cleverly done!', '2006-10-11 19:32:33.000000', NULL, 1),
(2920003, 408255, 3087, '<td valign="top">Dark! Subject matter supported well by wide angle perspective distortion, blue toning and high contrast treatment. Intriguing idea/ story too.</td>', 'Dark! Subject matter supported well by wide angle perspective distortion, blue toning and high contrast treatment. Intriguing idea/ story too.', '2006-10-11 19:33:39.000000', NULL, 1),
(2920006, 408437, 3087, '<td valign="top">Beautiful lighting and use of shadow creates wonderfully sculptural image which is perfect for the subject matter; the pose portrays a pride in both his body and his artistic/ performer nature.</td>', 'Beautiful lighting and use of shadow creates wonderfully sculptural image which is perfect for the subject matter; the pose portrays a pride in both his body and his artistic/ performer nature.', '2006-10-11 19:34:48.000000', NULL, 1),
(2920007, 408015, 3087, '<td valign="top">Interesting lighting, wonderful textures, story book content. Nice!</td>', 'Interesting lighting, wonderful textures, story book content. Nice!', '2006-10-11 19:35:14.000000', NULL, 1),
(2920011, 406551, 3087, '<td valign="top">How cool! Funky, quirky, well presented (in high contrast black and white)... Love both the idea and the execution.</td>', 'How cool! Funky, quirky, well presented (in high contrast black and white)... Love both the idea and the execution.', '2006-10-11 19:35:54.000000', NULL, 1),
(2920018, 406146, 45475, '<td valign="top">This may have worked better if the flash wasn''t so intrusive :)</td>', 'This may have worked better if the flash wasn''t so intrusive :)', '2006-10-11 19:37:58.000000', NULL, 1),
(2920019, 405140, 3087, '<td valign="top">Perfect example of the beauty and pleasure young children can find in the most everyday elements of the world around us... Love the backlighting on the flower. In this particular case I think a deeper depth of field would work better allowing both the dandelion head and the mouth to be in sharp focus though I still like it a lot as it is.</td>', 'Perfect example of the beauty and pleasure young children can find in the most everyday elements of the world around us... Love the backlighting on the flower. In this particular case I think a deeper depth of field would work better allowing both the dandelion head and the mouth to be in sharp focus though I still like it a lot as it is.', '2006-10-11 19:38:07.000000', NULL, 1),
(2920024, 408110, 3087, '<td valign="top">Clever way to show the inherent conflict in many teenage girls between their remaining childhood desire to just play, race around, get dirty, use up their energy and their desire to grow up more quickly and join the adult world of glamour and fashion and dating and independence...</td>', 'Clever way to show the inherent conflict in many teenage girls between their remaining childhood desire to just play, race around, get dirty, use up their energy and their desire to grow up more quickly and join the adult world of glamour and fashion and dating and independence...', '2006-10-11 19:40:11.000000', NULL, 1),
(2920025, 406151, 32754, '<td valign="top">I like the shadow and light impact on this image...it gives it strength and a dynamic feel, yet the fabric and sandal add a softness.</td>', 'I like the shadow and light impact on this image...it gives it strength and a dynamic feel, yet the fabric and sandal add a softness.', '2006-10-11 19:40:59.000000', NULL, 1),
