(2921928, 406670, 50695, '<td valign="top">fascinating title. I suppose some of us are defined by grief, at least for phases of our lives. 7</td>', 'fascinating title. I suppose some of us are defined by grief, at least for phases of our lives. 7', '2006-10-12 11:06:58.000000', NULL, 1),
(2921929, 406146, 5354, '<td valign="top">How can I say this without sounding rude. This doesn''t instill lust in me. The black and red top is nice enough, but the depth of field has left the neck and right breast horribly out of focus. The chin needs to be either in or out of the frame, not just on the edge. The skin at the armpit has blown out in the highlights except for that little spot bang on the edge of frame.<br/> <br/>There is sooo much you can improve on here. I hope the comments above are taken in the right way and help you understand how to present your work to better efect.</td>', 'How can I say this without sounding rude. This doesn''t instill lust in me. The black and red top is nice enough, but the depth of field has left the neck and right breast horribly out of focus. The chin needs to be either in or out of the frame, not just on the edge. The skin at the armpit has blown out in the highlights except for that little spot bang on the edge of frame. There is sooo much you can improve on here. I hope the comments above are taken in the right way and help you understand how to present your work to better efect.', '2006-10-12 11:07:23.000000', NULL, 1),
(2921931, 406158, 50695, '<td valign="top">excellent composition, but I am distracted by those vertical lines. 7</td>', 'excellent composition, but I am distracted by those vertical lines. 7', '2006-10-12 11:07:52.000000', NULL, 1),
(2921932, 408228, 5354, '<td valign="top">Nice clour, nice pose, nice props. Good lighting, good work.</td>', 'Nice clour, nice pose, nice props. Good lighting, good work.', '2006-10-12 11:08:24.000000', NULL, 1),
(2921935, 406591, 50695, '<td valign="top">fascinating mix of the mundane and the sublime, including not just the subject matter but the processing (mundane) and the crop (sublime). It''s this mix that makes the picture work for me. 7</td>', 'fascinating mix of the mundane and the sublime, including not just the subject matter but the processing (mundane) and the crop (sublime). It''s this mix that makes the picture work for me. 7', '2006-10-12 11:09:22.000000', NULL, 1),
(2921938, 408447, 5354, '<td valign="top">Isn''t that sky dreadful?<br/>A silhouette has to have somethiong to make it pop, and by definition it can''t be the silhouetted element. The sky is so dull that the whole tone of the image is just dreary. Sorry</td>', 'Isn''t that sky dreadful?A silhouette has to have somethiong to make it pop, and by definition it can''t be the silhouetted element. The sky is so dull that the whole tone of the image is just dreary. Sorry', '2006-10-12 11:10:10.000000', NULL, 1),
(2921940, 406874, 50695, '<td valign="top">creative fulfillment of the challenge and a moving picture. I think it''s the cobwebs that pull it all together for me. 7</td>', 'creative fulfillment of the challenge and a moving picture. I think it''s the cobwebs that pull it all together for me. 7', '2006-10-12 11:10:32.000000', NULL, 1),
(2921942, 408229, 50695, '<td valign="top">Dude, he rocked that place HARD.... it''s like... gone, now... 7</td>', 'Dude, he rocked that place HARD.... it''s like... gone, now... 7', '2006-10-12 11:11:22.000000', NULL, 1),
(2921944, 408277, 5354, '<td valign="top">Ahh yes the headless crop. Its an approach many people have taken to this challenge. In all but one or two cases the technique hasn''t really worked.</td>', 'Ahh yes the headless crop. Its an approach many people have taken to this challenge. In all but one or two cases the technique hasn''t really worked.', '2006-10-12 11:11:57.000000', NULL, 1),
(2921948, 408046, 50695, '<td valign="top">that cross is so ornate it says "biker" to me, rather than "preacher" 6</td>', 'that cross is so ornate it says "biker" to me, rather than "preacher" 6', '2006-10-12 11:12:46.000000', NULL, 1),
(2921949, 407470, 5354, '<td valign="top">Yes, I like it. Nice and colourful. Would have preferred to have had better control of the depth of field in order to make the background reced a little - make the farmer pop out of the iimage.</td>', 'Yes, I like it. Nice and colourful. Would have preferred to have had better control of the depth of field in order to make the background reced a little - make the farmer pop out of the iimage.', '2006-10-12 11:13:16.000000', NULL, 1),
(2921962, 406670, 5354, '<td valign="top">What are they? - the things that define us?<br/>The title is lost on me, I can''t associate it with what I''m looking at.<br/> <br/>However, this is supposed to be about the image so I''ll ignore the title.<br/> <br/>Nicely composed with the girl in the corner. Left half of the image is fine, but that big black cross is sort of lost in the big black trees. The tonal range selected probably has much to do with this. It might have been better just a little lighter to allow a differentiation between the cross and the trees.</td>', 'What are they? - the things that define us?The title is lost on me, I can''t associate it with what I''m looking at. However, this is supposed to be about the image so I''ll ignore the title. Nicely composed with the girl in the corner. Left half of the image is fine, but that big black cross is sort of lost in the big black trees. The tonal range selected probably has much to do with this. It might have been better just a little lighter to allow a differentiation between the cross and the trees.', '2006-10-12 11:16:20.000000', NULL, 1),
(2921981, 407952, 5354, '<td valign="top">Decently composed and executed image. I''m never particularly fond of religious images, but this is a better example of the type.</td>', 'Decently composed and executed image. I''m never particularly fond of religious images, but this is a better example of the type.', '2006-10-12 11:21:58.000000', NULL, 1),
(2921984, 407233, 5354, '<td valign="top">Nice socks</td>', 'Nice socks', '2006-10-12 11:22:48.000000', NULL, 1),
(2921990, 407958, 5354, '<td valign="top">That backdrop - what made you choose that?<br/>It competes with the main subject to such an extent it nearly drowns her out. Its brighter and more colourful, therefore the eyes are drawn to it. Meanwhile the lighting on the hair and right hand side of the image is almost dull in comparison. A simple solid neutral colour would have been much much better.</td>', 'That backdrop - what made you choose that?It competes with the main subject to such an extent it nearly drowns her out. Its brighter and more colourful, therefore the eyes are drawn to it. Meanwhile the lighting on the hair and right hand side of the image is almost dull in comparison. A simple solid neutral colour would have been much much better.', '2006-10-12 11:25:20.000000', NULL, 1),
(2922002, 408168, 5354, '<td valign="top">I''m guessing you want my eyes to rest on the right hand, on the fingers and bridge. Well they don''t - they slide off up the neck and ... oh bugger its uncomfortable up there coz its out of focus ... beter come back to the hand. Nope the eyes keep on sliding up that neck too and fro, nowhere to rest.<br/> <br/>We read images (or I read images) left to right. Always try to leave the eyye somewhere to rest, especially if you have strong leading lines as you have here.</td>', 'I''m guessing you want my eyes to rest on the right hand, on the fingers and bridge. Well they don''t - they slide off up the neck and ... oh bugger its uncomfortable up there coz its out of focus ... beter come back to the hand. Nope the eyes keep on sliding up that neck too and fro, nowhere to rest. We read images (or I read images) left to right. Always try to leave the eyye somewhere to rest, especially if you have strong leading lines as you have here.', '2006-10-12 11:28:40.000000', NULL, 1),
(2922008, 408419, 5354, '<td valign="top">Beautiful. Nothing more to say, simply beautiful!!</td>', 'Beautiful. Nothing more to say, simply beautiful!!', '2006-10-12 11:29:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2922023, 408518, 5354, '<td valign="top">Now I''m going to be rude here, and I apologise for that in advance.<br/>Why do you think anyone but the Mum, Dad or Grandparents would find this image appealing?<br/> <br/>It has no redeaming qualities as a published image. The lighting is flat, the composition is, ok it isn''t! There is dirt under the nails. <br/> <br/>No it is one of the most unappealing photos submitted to the challenge.<br/> <br/>Sorry if that hurts. Its a family snap.</td>', 'Now I''m going to be rude here, and I apologise for that in advance.Why do you think anyone but the Mum, Dad or Grandparents would find this image appealing? It has no redeaming qualities as a published image. The lighting is flat, the composition is, ok it isn''t! There is dirt under the nails.  No it is one of the most unappealing photos submitted to the challenge. Sorry if that hurts. Its a family snap.', '2006-10-12 11:33:21.000000', NULL, 1),
(2922024, 407278, 5354, '<td valign="top">Nice use of high contrast - would have done well last week ;-)</td>', 'Nice use of high contrast - would have done well last week ;-)', '2006-10-12 11:33:44.000000', NULL, 1),
