INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2924324, 408494, 60141, '<td valign="top">This image actually makes me laugh because it reminds me so much of those Mad Magazine Spy vs. Spy cartoons!  Love the background!</td>', 'This image actually makes me laugh because it reminds me so much of those Mad Magazine Spy vs. Spy cartoons!  Love the background!', '2006-10-12 23:47:11.000000', NULL, 1),
(2924365, 408306, 60141, '<td valign="top">This is an image that to me explores emotion conveyed through the eyes.  Her eyes are beautiful, but ultimately there are some technical issues which I think keep it from getting the full impact: the image is out of focus, the lighting is very bright, and you''ve chosen to show us a lot of the subject''s forehead instead of the color of her right eye (on our left) which I would have been more interested in.  Keep working on your technique, you''ve got some excellent ideas.</td>', 'This is an image that to me explores emotion conveyed through the eyes.  Her eyes are beautiful, but ultimately there are some technical issues which I think keep it from getting the full impact: the image is out of focus, the lighting is very bright, and you''ve chosen to show us a lot of the subject''s forehead instead of the color of her right eye (on our left) which I would have been more interested in.  Keep working on your technique, you''ve got some excellent ideas.', '2006-10-13 00:01:29.000000', NULL, 1),
(2924369, 405521, 60141, '<td valign="top">I know the feeling...sometimes you just have a beautiful image that you want folks to see, even if you know you''re gonna get a lot of DNMC comments...so here goes...<br/> <br/>Beautiful image.  DNMC.  There, I said it.</td>', 'I know the feeling...sometimes you just have a beautiful image that you want folks to see, even if you know you''re gonna get a lot of DNMC comments...so here goes... Beautiful image.  DNMC.  There, I said it.', '2006-10-13 00:04:08.000000', NULL, 1),
(2924377, 407850, 60141, '<td valign="top">I love the tender subject you''ve chosen to capture, but for me, the out-of-focus look, purple background and over-exposed skin tones, keep the image from getting to the next level. Keep working on the technical elements so that your photos can best represent the beauty of the subjects you''ve got.</td>', 'I love the tender subject you''ve chosen to capture, but for me, the out-of-focus look, purple background and over-exposed skin tones, keep the image from getting to the next level. Keep working on the technical elements so that your photos can best represent the beauty of the subjects you''ve got.', '2006-10-13 00:09:06.000000', NULL, 1),
(2924481, 407508, 22734, '<td valign="top">Colorful and very interesting.</td>', 'Colorful and very interesting.', '2006-10-13 01:14:53.000000', NULL, 1),
(2924482, 408534, 22734, '<td valign="top">Charming capture.</td>', 'Charming capture.', '2006-10-13 01:15:07.000000', NULL, 1),
(2924582, 408224, 57835, '<td valign="top">absolutely stunning</td>', 'absolutely stunning', '2006-10-13 02:02:51.000000', NULL, 1),
(2924662, 408001, 6247, '<td valign="top">This makes me think of something from a scary movie, but i love the monotone and the contrast.  Overall, this is a very good image and conveys the message quite well.</td>', 'This makes me think of something from a scary movie, but i love the monotone and the contrast.  Overall, this is a very good image and conveys the message quite well.', '2006-10-13 03:00:54.000000', NULL, 1),
(2924665, 408260, 6247, '<td valign="top">I absolutely LOVE this photo.  I love the use of red to balance the black.  It is very mysterious.  Absolutely perfect for this challenge!!</td>', 'I absolutely LOVE this photo.  I love the use of red to balance the black.  It is very mysterious.  Absolutely perfect for this challenge!!', '2006-10-13 03:02:52.000000', NULL, 1),
