(2928837, 408438, 51538, '<td valign="top">The angle of light certainly brings out the veins and texture of the geode.  All in all, an interesting piece of work. 9.</td>', 'The angle of light certainly brings out the veins and texture of the geode.  All in all, an interesting piece of work. 9.', '2006-10-14 19:26:54.000000', NULL, 1),
(2928838, 408427, 51538, '<td valign="top">I like the portrait here and can easily identify with the feeling captured. 8.</td>', 'I like the portrait here and can easily identify with the feeling captured. 8.', '2006-10-14 19:27:30.000000', NULL, 1),
(2928842, 408213, 51538, '<td valign="top">Nice painterly image.  I like the muted colours and the composition. 9.</td>', 'Nice painterly image.  I like the muted colours and the composition. 9.', '2006-10-14 19:28:02.000000', NULL, 1),
(2928843, 408255, 51538, '<td valign="top">I like your creative composition.  All works wonderfully to express some sort of overload. 9.</td>', 'I like your creative composition.  All works wonderfully to express some sort of overload. 9.', '2006-10-14 19:28:53.000000', NULL, 1),
