(2929464, 408275, 13688, '<td valign="top">i''m intrigued by your undulating background</td>', 'i''m intrigued by your undulating background', '2006-10-15 01:40:46.000000', NULL, 1),
(2929482, 407725, 13688, '<td valign="top">great pose.  Fantastic idea to create the lit look of the head.  i''ll get picky and wish you softened the hair outline, as it looks like it was selected with the straight outline tool.  Perhaps the blotchiness was intentional to create a  marble/statue look, but I really would like to see this smoothed out.</td>', 'great pose.  Fantastic idea to create the lit look of the head.  i''ll get picky and wish you softened the hair outline, as it looks like it was selected with the straight outline tool.  Perhaps the blotchiness was intentional to create a  marble/statue look, but I really would like to see this smoothed out.', '2006-10-15 01:52:09.000000', NULL, 1),
(2929485, 408337, 43434, '<td valign="top">The shadows on the wall are from the model being too close and do''not tend to flatter this rather good image.</td>', 'The shadows on the wall are from the model being too close and do''not tend to flatter this rather good image.', '2006-10-15 01:54:19.000000', NULL, 1),
(2929505, 407040, 43434, '<td valign="top">Picture is a little too small ... maximising the image helps to give really good impact.</td>', 'Picture is a little too small ... maximising the image helps to give really good impact.', '2006-10-15 02:04:50.000000', NULL, 1),
(2929507, 408271, 43434, '<td valign="top">I found the heavy black border detracts a little ... but not significantly ...</td>', 'I found the heavy black border detracts a little ... but not significantly ...', '2006-10-15 02:06:00.000000', NULL, 1),
(2929509, 407850, 43434, '<td valign="top">The created border being incompleted does not seem to add anything to this picture.</td>', 'The created border being incompleted does not seem to add anything to this picture.', '2006-10-15 02:06:25.000000', NULL, 1),
(2929516, 406874, 43434, '<td valign="top">Very strong political statement here ..</td>', 'Very strong political statement here ..', '2006-10-15 02:09:28.000000', NULL, 1),
