(2932078, 408015, 50231, '<td valign="top">Man this was my blue ribbon pick! Fantastic Crystal just fantastic.</td>', 'Man this was my blue ribbon pick! Fantastic Crystal just fantastic.', '2006-10-16 02:56:29.000000', NULL, 0),
