(2932929, 408015, 39057, '<td valign="top">Wow...nice job.</td>', 'Wow...nice job.', '2006-10-16 10:30:19.000000', NULL, 0),
(2932933, 408490, 53572, '<td valign="top">i tought this was yours, shez.  i love the bright colours on the face, and the fact that you can see the forms of his face beneath the wrapping.  i think it might be improved with a darker tone on the background - it''s a very strong, pure blue, and is quite distracting.</td>', 'i tought this was yours, shez.  i love the bright colours on the face, and the fact that you can see the forms of his face beneath the wrapping.  i think it might be improved with a darker tone on the background - it''s a very strong, pure blue, and is quite distracting.', '2006-10-16 10:31:10.000000', NULL, 0),
