(2954421, 408021, 1031, '<td valign="top">Here''s the picture he was taking:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=415871" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/1031/thumb/415871.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/1031/thumb/415871.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/1031/thumb/415871.jpg"/></a></td>', 'Here''s the picture he was taking: ', '2006-10-23 13:26:43.000000', NULL, 0),
